days span{display:inline-flex;align-items:center;margin:8px 8px 0 0}.weekdays input{width:auto}.setup-storage{display:grid;gap:12px}.setup-status-row{display:flex;align-items:center;gap:12px;padding-top:10px;border-top:1px solid #edf0f4;color:#667386;font-size:11px}.setup-status-row>b{color:#344257;min-width:180px}.setup-status-row .quiet{margin-left:auto}@media(max-width:1000px){.setup-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.provider-grid{grid-template-columns:1fr}}@media(max-width:600px){.setup-grid{grid-template-columns:1fr}.setup-intro,.provider-title{align-items:flex-start;flex-direction:column}.setup-status-row{align-items:flex-start;flex-direction:column}.setup-status-row .quiet{margin:0}}
